DOMAIN = 'Spec Catalog Pending Patents'

import time

def bench(fn, n):
    t0 = time.perf_counter()
    for _ in range(n):
        fn()
    dt = time.perf_counter() - t0
    return int(n / dt) if dt > 0 else n

records = [{"title": "r" + str(i), "ladder": (i % 3) + 1} for i in range(200)]
def catalog_op():
    return [r for r in records if "r1" in r["title"]]
def scoring_op():
    return sum([8, 9, 7, 8, 10])
def generation_op():
    return "Signature " + DOMAIN + " variant " + str(len(records))

print("catalog benchmark:", bench(catalog_op, 2000), "ops/sec")
print("scoring benchmark:", bench(scoring_op, 2000), "ops/sec")
print("generation benchmark:", bench(generation_op, 2000), "ops/sec")
print("Benchmarks published for", DOMAIN)

